// FlowKit - clinic appointment reminders (part B)
// 1) Set these two values before activating the workflow.
const BASE_URL = 'https://your-n8n.example.com';
const CLINIC_NAME = 'your clinic';

const NL = String.fromCharCode(10);
const today = new Date();
today.setHours(0, 0, 0, 0);
const tomorrow = new Date(today.getTime() + 86400000);

// Accepts ISO (2026-11-12), ISO with time, DD/MM/YYYY and Date objects.
function parseDate(v) {
  if (!v) return null;
  if (v instanceof Date) return new Date(v.getFullYear(), v.getMonth(), v.getDate());
  let s = String(v).trim();
  if (s.length >= 10 && s.charAt(4) === '-') s = s.slice(0, 10);
  let p = s.split('/');
  if (p.length === 3) return new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  p = s.split('-');
  if (p.length === 3) {
    if (p[0].length === 4) return new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
    return new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function dateText(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return dd + '/' + mm + '/' + d.getFullYear();
}

const base = BASE_URL.endsWith('/') ? BASE_URL.slice(0, -1) : BASE_URL;
const rows = $input.all().map(i => i.json);
const output = [];

for (const c of rows) {
  const status = String(c.Status || 'Pending').trim().toLowerCase();
  if (status.indexOf('cancel') === 0 || status.indexOf('attend') === 0) continue;
  const f = parseDate(c.Date);
  if (!f || f.getTime() !== tomorrow.getTime()) continue;
  const email = String(c.Email || '').trim();
  if (!email) continue;
  const id = String(c.ID || '').trim();
  if (!id) continue;

  const name = String(c.Patient || 'there').trim() || 'there';
  const time = String(c.Time || '').trim() || 'the agreed time';
  const when = dateText(tomorrow);
  const link = base + '/webhook/flowkit-appointment?id=' + encodeURIComponent(id) + '&date=' + encodeURIComponent(when) + '&time=' + encodeURIComponent(time) + '&action=';
  const confirmUrl = link + 'confirm';
  const cancelUrl = link + 'cancel';

  const subject = 'Appointment reminder: ' + when + ' at ' + time;
  const body = [
    'Hello ' + name + ',',
    '',
    'This is a reminder of your appointment at ' + CLINIC_NAME + ' on ' + when + ' at ' + time + '.',
    '',
    'Confirm your attendance here:',
    confirmUrl,
    '',
    'If you cannot make it, cancel here so we can offer the slot to another patient:',
    cancelUrl,
    '',
    'If you have already confirmed or cancelled, please ignore this message.'
  ].join(NL);

  output.push({ json: { to: email, subject: subject, body: body, id: id } });
}

return output;

// FlowKit - tomorrow's agenda (part B)
const NL = String.fromCharCode(10);
const today = new Date();
today.setHours(0, 0, 0, 0);
const tomorrow = new Date(today.getTime() + 86400000);

function parseDate(v) {
  if (!v) return null;
  if (v instanceof Date) return new Date(v.getFullYear(), v.getMonth(), v.getDate());
  let s = String(v).trim();
  if (s.length >= 10 && s.charAt(4) === '-') s = s.slice(0, 10);
  let p = s.split('/');
  if (p.length === 3) return new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  p = s.split('-');
  if (p.length === 3) {
    if (p[0].length === 4) return new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
    return new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function dateText(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return dd + '/' + mm + '/' + d.getFullYear();
}

const rows = $input.all().map(i => i.json);
const appointments = [];

for (const c of rows) {
  const status = String(c.Status || 'Pending').trim();
  const lower = status.toLowerCase();
  if (lower.indexOf('cancel') === 0 || lower.indexOf('attend') === 0) continue;
  const f = parseDate(c.Date);
  if (!f || f.getTime() !== tomorrow.getTime()) continue;
  appointments.push({
    time: String(c.Time || '').trim(),
    patient: String(c.Patient || 'unnamed').trim(),
    treatment: String(c.Treatment || 'consultation').trim(),
    status: status || 'Pending',
    email: String(c.Email || '').trim()
  });
}

if (appointments.length === 0) return [];

appointments.sort((a, b) => String(a.time).localeCompare(String(b.time)));
const lines = appointments.map(a => '- ' + (a.time || '--:--') + ' | ' + a.patient + ' | ' + a.treatment + ' | ' + a.status + (a.email ? '' : ' | NO EMAIL'));
const text = 'Tomorrow\'s agenda (' + dateText(tomorrow) + '): ' + appointments.length + ' appointment(s)' + NL + NL + lines.join(NL) + NL + NL + 'Patients with an email address received the reminder with confirm/cancel links.';

return [{ json: { text: text, total: appointments.length, date: dateText(tomorrow) } }];

// FlowKit - patient link handler (part C)
const NL = String.fromCharCode(10);
const q = ($json.query && typeof $json.query === 'object') ? $json.query : {};
const id = String(q.id || '').trim();
const action = String(q.action || '').trim().toLowerCase();
const date = String(q.date || '').trim();
const time = String(q.time || '').trim();

const ok = id.length > 0 && (action === 'confirm' || action === 'cancel');
const confirmed = action === 'confirm';
const newStatus = ok ? (confirmed ? 'Confirmed' : 'Cancelled') : '';

const title = ok ? (confirmed ? 'Appointment confirmed' : 'Appointment cancelled') : 'Invalid link';
const message = ok
  ? (confirmed
      ? 'Thank you. Your confirmation has been recorded and the clinic has been notified.'
      : 'Your cancellation has been recorded. The clinic has been notified so the slot can be offered to another patient.')
  : 'This link does not contain a valid appointment. If you need to change your appointment, please contact the clinic directly.';
const color = ok ? (confirmed ? '#0a7d32' : '#b3261e') : '#6b7280';

const slot = (date || time) ? (date + (time ? ' at ' + time : '')) : 'not included in the link';
const notice = ok
  ? ('Appointment ' + (confirmed ? 'CONFIRMED' : 'CANCELLED') + ' by the patient' + NL + 'ID: ' + id + (confirmed ? '' : NL + NL + 'Freed slot: ' + slot + NL + 'Check the agenda and offer it to another patient.'))
  : ('Invalid appointment link' + NL + 'ID: ' + (id || '(empty)') + ' - Action: ' + (action || '(empty)'));

const html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + title + '</title></head><body style="margin:0;padding:40px 16px;background:#f6f7f9;font-family:system-ui,-apple-system,Segoe UI,sans-serif;"><main style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px;text-align:center;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><h1 style="margin:0 0 12px;font-size:24px;color:' + color + ';">' + title + '</h1><p style="margin:0;font-size:16px;line-height:1.5;color:#333333;">' + message + '</p><p style="margin:24px 0 0;font-size:13px;color:#888888;">You can close this page.</p></main></body></html>';

return [{ json: { ok: ok, id: id, action: action, newStatus: newStatus, notice: notice, html: html } }];
